 * @description btn_PrelistPageSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_PrelistPageSearch_onclick = async function(e){
    try {
        await scwin.prelistPageSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05003.btn_PrelistPageSearch_onclick' }); }
