/**
 * @method
 * @name vailidationLn
 * @description vailidation Ln 처리
 * @param {String} invstgClmTpCd invstgClmTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.vailidationLn = async function (invstgClmTpCd) {
    if (!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) {
        return false;
    }
    if (invstgClmTpCd !== 5) {
        if ($c.util.getComponent('ipt_fsttrmCap').getValue().length <= 0 || $c.util.getComponent('ipt_fsttrmCap').getValue()=== "0") {
            await $c.win.alert("자본금(전기)을 정확히 입력해주십시요.");
            $c.util.getComponent("ipt_fsttrmCap").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
            return false;
        }
        if ($c.util.getComponent('ipt_fsttrmSales').getValue().length <= 0 || $c.util.getComponent('ipt_fsttrmSales').getValue()=== "0") {
            await $c.win.alert("매출액(전기)을 정확히 입력해주십시요.");
            $c.util.getComponent("ipt_fsttrmSales").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    const invstgClmTpCd = $c.util.getComponent('dma_RegisterReq').get('invstgClmTpCd');
    if (await scwin.vailidationLn(invstgClmTpCd) === false) {
        return;
    }
    scwin.rmCommaValueAll(invstgClmTpCd);
    scwin.form.action = '/list/prelist.do';
    $c.util.getComponent('dma_RegisterReq').set('method', 'prelistReg');
    await scwin.tx_fn_Register();
};

