    $c.util.getComponent('ipt_halfFixasstAmt').setValue($c.num.formatNumber(
            scwin.rmComma($c.util.getComponent('ipt_halfInvstasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_halfTanasstAmt').getValue())
            + scwin.rmComma($c.util.getComponent('ipt_halfIntanasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_halfMiscFixasstAmt').getValue()) ));

    if(invstgClmTpCd !== 5) {
        $c.util.getComponent('ipt_fsttrmFixasstAmt').setValue($c.num.formatNumber(
                scwin.rmComma($c.util.getComponent('ipt_fsttrmInvstasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_fsttrmTanasstAmt').getValue())
                + scwin.rmComma($c.util.getComponent('ipt_fsttrmIntanasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_fsttrmMiscFixasstAmt').getValue()) ));

        $c.util.getComponent('ipt_scndtrmFixasstAmt').setValue($c.num.formatNumber(
                scwin.rmComma($c.util.getComponent('ipt_scndtrmInvstasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_scndtrmTanasstAmt').getValue())
                + scwin.rmComma($c.util.getComponent('ipt_scndtrmIntanasstAmt').getValue()) + scwin.rmComma($c.util.getComponent('ipt_scndtrmMiscFixasstAmt').getValue())));
    }

    fn_CalcAssetSum(); // 자산총계  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_CalcAssetSum — as-is 공통(폼 전역 의존) — 반입 보류

};

